SELECT p.gender, s.age, s.hadm_id, s.first_careunit, s.intime, s.outtime, s.los, s.deathtime, v.vital_instability_index, percentile_cont(0.25) within GROUP (ORDER BY v.vital_instability_index) AS q25, percentile_cont(0.75) within GROUP (ORDER BY v.vital_instability_index) AS q75, percentile_cont(0.95) within GROUP (ORDER BY v.vital_instability_index) AS q95, stddev(v.vital_instability_index) AS sd FROM patients p JOIN icustays s ON p.subject_id = s.subject_id JOIN chartevents c ON s.subject_id = c.subject_id AND s.hadm_id = c.hadm_id AND s.stay_id = c.stay_id JOIN vital_signs v ON c.itemid = v.vital_sign_code AND c.charttime BETWEEN v.vital_sign_time AND v.vital_sign_time + interval '48 hours' WHERE p.gender = 'M' AND s.first_careunit = 'ICU' AND s.intime BETWEEN p.dob AND p.dob + interval '48 hours' AND s.outtime BETWEEN p.dob + interval '48 hours' AND p.dob + interval '72 hours' AND s.los <= interval '48 hours' AND (c.value < 65 OR c.value > 140) AND (c.value_uom = 'mmHg' OR c.value_uom = 'mg/dL') AND (c.charttime - s.intime) <= interval '48 hours' AND (c.charttime - s.intime) >= interval '0 hours' AND (c.value_uom = 'bpm' OR c.value_uom = 'per_min') AND (c.value < 100 OR c.value > 150) GROUP BY p.gender, s.age, s.hadm_id, s.first_careunit, s.intime, s.outtime, s.los, s.deathtime, v.vital_instability_index;